//! CPS1 / CPS2 player inputs, from MAME's input port definitions (cps_input_tables.rs,
//! generated by tools/cps1/cps_inputs_gen.py). Each set has a layout: which bit of which
//! port is which player's joystick, button, start or coin, so 3 / 4-player games, 6-button
//! games, Slam Masters' button 3 for players 3 / 4 and the quiz games' fourth button all come
//! from MAME's data instead of special cases here.
//!
//! Pad buttons to arcade buttons:
//! - 6-button games (any button 5 or 6 in the layout): Y X L = buttons 1-3 (punches),
//!   B A R = buttons 4-6 (kicks), on every pad.
//! - the rest: B A X Y = buttons 1-4.
//!
//! Pad 1's Z is the test / service switch.

use crate::common::input::Pad;

pub use super::cps_input_tables::{cps1_layout, cps2_layout};

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Kind {
    Right,
    Left,
    Down,
    Up,
    /// button 1-6
    Button(u8),
    Start,
    Coin,
    /// test / service mode switch
    Test,
    /// service coin
    ServiceCoin,
}

#[derive(Clone, Copy, Debug)]
pub struct Bind {
    pub port: u8,
    pub mask: u16,
    /// 0-3
    pub player: u8,
    pub kind: Kind,
    pub active_high: bool,
}

#[derive(Debug)]
pub struct InputLayout {
    /// port values with nothing pressed
    pub idle: [u16; 4],
    pub binds: &'static [Bind],
}

impl InputLayout {
    pub fn six_button(&self) -> bool {
        self.binds.iter().any(|b| matches!(b.kind, Kind::Button(5) | Kind::Button(6)))
    }

    /// The input port values for these pads.
    pub fn ports(&self, pads: &[Pad; 4]) -> [u16; 4] {
        let six = self.six_button();
        let mut out = self.idle;
        for b in self.binds {
            let p = &pads[b.player as usize & 3];
            let pressed = match b.kind {
                Kind::Right => p.right,
                Kind::Left => p.left,
                Kind::Down => p.down,
                Kind::Up => p.up,
                Kind::Button(n) => {
                    let buttons = if six { [p.y, p.x, p.l, p.b, p.a, p.r] } else { [p.b, p.a, p.x, p.y, false, false] };
                    buttons.get(n as usize - 1).copied().unwrap_or(false)
                }
                Kind::Start => p.start,
                Kind::Coin => p.coin,
                Kind::Test => b.player == 0 && p.z,
                Kind::ServiceCoin => false,
            };
            if pressed {
                let o = &mut out[b.port as usize & 3];
                if b.active_high { *o |= b.mask } else { *o &= !b.mask }
            }
        }
        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::common::input::{pads, A, B, P2_SHIFT};

    #[test]
    fn active_high_bits_are_set_and_active_low_bits_cleared() {
        static L: InputLayout = InputLayout {
            idle: [0x00F0, 0xFFFF, 0xFFFF, 0xFFFF],
            binds: &[
                Bind { port: 0, mask: 0x0001, player: 1, kind: Kind::Button(1), active_high: true },
                Bind { port: 0, mask: 0x0010, player: 1, kind: Kind::Button(2), active_high: false },
            ],
        };
        assert_eq!(L.ports(&pads((B | A) << P2_SHIFT, 0))[0], 0x00E1);
        assert_eq!(L.ports(&pads(0, 0))[0], 0x00F0);
    }
}
